 {Bytes ram=base_ram("");put(ram,NODE+0x19,1,0x81);put(ram,NODE+0x15,1,0xee);State s=st(0x1d10a);Out o;check(run(ram,s,STOP,o)&&get(ram,NODE+0x14,1)==0x81U&&get(ram,NODE+0x15,1)==0xeeU,"1d10a");}
