 {Bytes ram=base_ram("");State s=st(0x1d1e2);s.d[0]=0x12345678U;Out o;check(run(ram,s,0x28ae,o)&&s.a[0]==0x361e4U&&s.d[0]==0x1234000aU&&get(ram,SP-4U,4)==0x1d1f2U,"1d1e2");}
 // ---- 1d222: D0.W := WORD 76; BSR 1d198.  1d22a: the node reset, BSET D0 (WORD 78 modulo 8) of BYTE 60, JSR 1aa3a.
 {Bytes ram=base_ram("");put(ram,NODE+0x76,2,0x8001);State s=st(0x1d222);s.d[0]=0x12345678U;Out o;check(run(ram,s,0x1d198,o)&&s.d[0]==0x12348001U&&get(ram,SP-4U,4)==0x1d22aU,"1d222");}
 {Bytes ram=ff_node();put(ram,NODE+0x78,2,0x000b);put(ram,NODE+0x60,1,0);State s=st(0x1d22a);s.d[0]=0x12345678U;Out o;
  check(run(ram,s,0x1aa3a,o)&&get(ram,SP-4U,4)==0x1d2d4U&&s.d[0]==0x1234000bU,"1d22a");
  check(get(ram,NODE+0x61,1)==0x7fU&&get(ram,NODE+0x15,1)==0xffU&&get(ram,NODE+0x60,1)==0x08U,"1d22a BCLR #7,61 / BSET #6,15 / BSET 11 mod 8");
  check(get(ram,NODE+0x68,2)==0x8834U&&get(ram,NODE+0x1e,2)==0x8834U&&get(ram,NODE+0x56,4)==0U&&get(ram,NODE+0x84,4)==0x21602U,"1d22a WORDs and LONGs");
  check(get(ram,NODE+0x9c,1)==0U&&get(ram,NODE+0xaa,1)==1U&&get(ram,NODE+0x7a,2)==0U&&get(ram,NODE+0x36,4)==0U&&get(ram,NODE+0x3a,4)==0U&&get(ram,NODE+0x64,4)==0U,"1d22a slot");
  check(get(ram,NODE+0xa9,1)==0U&&get(ram,NODE+0x92,2)==0U&&get(ram,NODE+0xb6,2)==0xffffU&&get(ram,NODE+0xb8,2)==0U&&get(ram,NODE+0xb2,4)==0U,"1d22a tail");
  const std::uint32_t z[11]={0x9d,0xa4,0xa5,0xa2,0xa3,0xab,0xac,0xad,0xa7,0xa8,0xa6};
  for(unsigned int i=0;i<11U;++i)check(get(ram,NODE+z[i],1)==0U,"1d22a CLR.B",z[i]);
  const std::uint32_t keep[18]={0x55,0x5a,0x83,0x88,0x9b,0x9e,0xa0,0xa1,0xae,0xb1,0xba,0x7c,0x94,0x6a,0x20,0x1d,0x7d,0x35};
  for(unsigned int i=0;i<18U;++i)check(get(ram,NODE+keep[i],1)==0xffU,"1d22a neighbours kept",keep[i]);}
 // 1d2d4: D1.W := D0.W; bit 5 set -> 1d2e6, clear -> 1d2de (CLR.W 8(A4) with A4 := LONG 8c).
 {Bytes ram=base_ram("");put(ram,NODE+0x8c,4,PARENT);put(ram,PARENT+8,4,0xffffffffU);State s=st(0x1d2d4);s.d[0]=0x12345600U;s.d[1]=0xabcd1111U;Out o;
  check(run(ram,s,0x1d2e6,o)&&s.d[1]==0xabcd5600U&&s.a[4]==PARENT&&get(ram,PARENT+8,4)==0x0000ffffU,"1d2d4 / 1d2de");}
 {Bytes ram=base_ram("");State s=st(0x1d2d4);s.d[0]=0x20U;check(ends_at(ram,s,0x1d2e6),"1d2d4 bit 5");}
 // 1d2e6..1d304: D0 := 5, bit 3 -> 3, bit 6 -> 4, bit 10 (register BTST) -> 7 (MOVEQ: the whole LONG).
 {const std::uint32_t d1[5]={0,8,0x40,0x400,0x448},want[5]={5,3,4,7,7};
  for(unsigned int i=0;i<5U;++i){Bytes ram=base_ram("");State s=st(0x1d2e6);s.d[1]=d1[i];s.d[0]=0xffffffffU;Out o;check(run(ram,s,0x1d306,o)&&s.d[0]==want[i],"1d2e6 pose",d1[i]);}}
 {Bytes ram=base_ram("");State s=st(0x1d2e6);s.d[1]=0x40000U;s.d[0]=0;Out o;check(run(ram,s,0x1d306,o)&&s.d[0]==5U,"1d2fc bit 10 only");}
 {Bytes ram=base_ram("");State s=st(0x1d306);s.a[0]=0;Out o;check(run(ram,s,0x1c1f4,o)&&s.a[0]==NODE&&get(ram,SP-4U,4)==0x1d30cU,"1d306");}
 {Bytes ram=base_ram("");State s=st(0x1d30c);Out o;check(run(ram,s,0x1c1e2,o)&&get(ram,SP-4U,4)==0x1d310U,"1d30c");}
 {Bytes ram=base_ram("");State s=st(0x1d310);Out o;check(run(ram,s,0x1d15a,o)&&get(ram,SP-4U,4)==0x1d314U,"1d310");}
 {Bytes ram=base_ram("");put(ram,NODE+0x78,2,0x8001);State s=st(0x1d314);s.d[0]=0x12345678U;Out o;check(run(ram,s,0xe8b5a,o)&&s.d[0]==0x12348001U&&get(ram,SP-4U,4)==0x1d31eU,"1d314");}
 // 1d31e: CMPI.W #0,D7 (WORD): 10000 -> 1d45a, 8000 -> 1d326 (MOVE.W D7,-(A7); JSR ea5f0).
 {Bytes ram=base_ram("");State s=st(0x1d31e);s.d[7]=0x10000U;check(ends_at(ram,s,0x1d45a),"1d31e WORD");}
 {Bytes ram=base_ram("");State s=st(0x1d31e);s.d[7]=0x8000U;check(ends_at(ram,s,0x1d326),"1d31e 8000");}
 {Bytes ram=base_ram("");State s=st(0x1d326);s.d[7]=0x12340004U;Out o;check(run(ram,s,0xea5f0,o)&&get(ram,SP-2U,2)==4U&&get(ram,SP-6U,4)==0x1d32eU&&s.a[7]==SP-6U,"1d326");}
 // 1d32e / 1d344: A4 := LONG 8c; D0.B := BYTE 4(A4); D7 := 6f1c4; 10 / 11 -> 1d352, else 1d380.  1d352: A0 := D7, D0.W := a, A1 := 100bf4, JSR 2986.
 {Bytes ram=base_ram("");put(ram,NODE+0x8c,4,PARENT);put(ram,PARENT+4,1,0x10);State s=st(0x1d32e);s.d[0]=0x12345678U;s.d[7]=0;Out o;
  check(run(ram,s,0x1d352,o)&&s.d[0]==0x12345610U&&s.d[7]==0x6f1c4U&&s.a[4]==PARENT,"1d32e 10");}
 {Bytes ram=base_ram("");put(ram,REC+4,1,0x11);put(ram,NODE+0x8c,4,REC);State s=st(0x1d32e);Out o;check(run(ram,s,0x1d352,o)&&s.d[7]==0x6f1c4U,"1d344 11");}
 {Bytes ram=base_ram("");put(ram,REC+4,1,0x90);put(ram,NODE+0x8c,4,REC);State s=st(0x1d32e);check(ends_at(ram,s,0x1d380),"1d344 90");}
 {Bytes ram=base_ram("");State s=st(0x1d344);s.d[0]=0x111U;s.d[7]=0;Out o;check(run(ram,s,0x1d352,o)&&s.d[7]==0x6f1c4U,"1d344 BYTE compare (111 -> 11)");}
 {Bytes ram=base_ram("");State s=st(0x1d352);s.d[7]=0x6f1c4;s.d[0]=0x12345678U;Out o;
  check(run(ram,s,0x2986,o)&&s.a[0]==0x6f1c4U&&s.d[0]==0x1234000aU&&s.a[1]==0x100bf4U&&get(ram,SP-4U,4)==0x1d364U,"1d352");}
 // 1d364: WORD 76(A0) := WORD 78(A6); D0.W := WORD 42; D1.W := 200; A1 := 0; A0 += 2e; JSR 43e08.
 {Bytes ram=base_ram("");put(ram,NODE+0x78,2,0x8001);put(ram,NODE+0x42,2,0x1234);State s=st(0x1d364);s.a[0]=CHILD;s.a[1]=0xffffffffU;s.d[0]=0xabcd0000U;s.d[1]=0xabcd0000U;Out o;
  check(run(ram,s,0x43e08,o)&&get(ram,CHILD+0x76,2)==0x8001U&&s.d[0]==0xabcd1234U&&s.d[1]==0xabcd0200U&&s.a[1]==0U&&s.a[0]==CHILD+0x2eU&&
   get(ram,SP-4U,4)==0x1d380U,"1d364");}
 // 1d380: WORD 90 := 78; D7.W := the popped WORD (upper kept); 1 -> 1de3c, 4 -> 1ddd0, else 1d398 (C6).
